1	//! Shared helper functions for common card resolution patterns.
2	//!
3	//! Includes:
4	//! - Spell resolution helpers (resolve_aura, resolve_damage, resolve_destroy)
5	//! - Choice presentation helpers (present_target_choice, present_yes_no, etc.)
6	//! - Target collection helpers (any_targets, creature_targets, etc.)
7	
8	use crate::actions::Target;
9	use crate::cards::CardRegistry;
10	use crate::events::{DamageTarget, GameEvent};
11	use crate::ids::{ObjectId, PlayerId};
12	use crate::state::{AwaitingAction, GameState, LogLevel, PendingEffect, ResolutionChoiceKind};
13	use crate::types::Zone;
14	
15	/// Resolve an aura spell: attach it to the target creature on the battlefield.
16	/// If the target is no longer on the battlefield, the aura goes to graveyard.
17	/// Returns true if the aura was successfully attached.
18	pub fn resolve_aura(state: &mut GameState, aura_id: ObjectId, targets: &[Target]) -> bool {
19	    if let Some(Target::Object(target_id)) = targets.first() {
20	        if state.get_object(*target_id).map(|o| o.zone == Zone::Battlefield).unwrap_or(false) {
21	            state.move_object(aura_id, Zone::Battlefield);
22	            if let Some(obj) = state.get_object_mut(aura_id) {
23	                obj.attached_to = Some(*target_id);
24	                obj.summoning_sick = false;
25	            }
26	            return true;
27	        }
28	    }
29	    state.move_spell_after_resolve(aura_id);
30	    false
31	}
32	
33	/// Resolve a curse aura: attach to a target player and move to battlefield.
34	pub fn resolve_curse(state: &mut GameState, curse_id: ObjectId, targets: &[Target]) -> bool {
35	    if let Some(Target::Player(player_id)) = targets.first() {
36	        state.move_object(curse_id, Zone::Battlefield);
37	        if let Some(obj) = state.get_object_mut(curse_id) {
38	            obj.attached_to_player = Some(*player_id);
39	            obj.summoning_sick = false;
40	        }
41	        return true;
42	    }
43	    state.move_spell_after_resolve(curse_id);
44	    false
45	}
46	
47	/// Resolve a damage spell: deal `amount` damage to the first target
48	/// (creature or player), then move the spell to the appropriate zone.
49	pub fn resolve_damage(state: &mut GameState, spell_id: ObjectId, targets: &[Target], amount: u32) {
50	    if let Some(target) = targets.first() {
51	        match target {
52	            Target::Object(target_id) => {
53	                if let Some(obj) = state.get_object_mut(*target_id) {
54	                    if obj.zone == Zone::Battlefield {
55	                        obj.damage_marked += amount;
56	                        obj.damaged_by.push(spell_id);
57	                        state.events.push(GameEvent::NonCombatDamageDealt {
58	                            source: spell_id,
59	                            target: DamageTarget::Object(*target_id),
60	                            amount,
61	                        });
62	                    }
63	                }
64	            }
65	            Target::Player(player_id) => {
66	                let old_life = state.get_player(*player_id).life;
67	                let new_life = old_life - (amount as i32);
68	                state.get_player_mut(*player_id).life = new_life;
69	                state.events.push(GameEvent::NonCombatDamageDealt {
70	                    source: spell_id,
71	                    target: DamageTarget::Player(*player_id),
72	                    amount,
73	                });
74	                state.events.push(GameEvent::LifeChanged {
75	                    player: *player_id,
76	                    old: old_life,
77	                    new_life,
78	                });
79	            }
80	        }
81	    }
82	    state.move_spell_after_resolve(spell_id);
83	}
84	
85	/// Resolve a targeted destruction spell: destroy the first target creature
86	/// via the destruction pipeline (checks indestructible/regeneration),
87	/// then move the spell to the appropriate zone.
88	pub fn resolve_destroy(
89	    state: &mut GameState,
90	    spell_id: ObjectId,
91	    targets: &[Target],
92	    registry: &crate::cards::CardRegistry,
93	) {
94	    if let Some(Target::Object(target_id)) = targets.first() {
95	        if let Some(obj) = state.get_object(*target_id) {
96	            if obj.zone == Zone::Battlefield {
97	                crate::destruction::try_destroy(state, *target_id, registry);
98	            }
99	        }
100	    }
101	    state.move_spell_after_resolve(spell_id);
102	}
103	
104	// ═══════════════════════════════════════════════════════════════════
105	// Choice presentation helpers
106	//
107	// These set up AwaitingAction::ResolutionChoice so the game loop
108	// asks the player to make a decision. The CLI and LLM player both
109	// know how to render these choices.
110	// ═══════════════════════════════════════════════════════════════════
111	
112	/// Present a "choose one target" choice to the player.
113	///
114	/// - If `targets` is empty, does nothing.
115	/// - If mandatory (`optional == false`) and exactly 1 target, auto-applies the effect.
116	/// - Otherwise, sets up a ResolutionChoice for the player to pick.
117	pub fn present_target_choice(
118	    state: &mut GameState,
119	    source_id: ObjectId,
120	    controller: PlayerId,
121	    targets: Vec<Target>,
122	    effect: PendingEffect,
123	    description: &str,
124	    optional: bool,
125	) {
126	    if targets.is_empty() {
127	        return;
128	    }
129	    if targets.len() == 1 && !optional {
130	        // Mandatory with exactly 1 target — auto-apply.
131	        let reg = crate::cards::CardRegistry::with_all_cards();
132	        crate::engine::apply_pending_effect(state, &targets[0], &effect, &reg);
133	        return;
134	    }
135	    state.awaiting_action = Some(AwaitingAction::ResolutionChoice {
136	        player: controller,
137	        source: source_id,
138	        choice: ResolutionChoiceKind::ChooseTarget {
139	            description: description.into(),
140	            options: targets,
141	            optional,
142	            effect,
143	        },
144	    });
145	}
146	
147	/// Present a "choose one target" choice that is optional ("you may").
148	pub fn present_optional_target_choice(
149	    state: &mut GameState,
150	    source_id: ObjectId,
151	    controller: PlayerId,
152	    targets: Vec<Target>,
153	    effect: PendingEffect,
154	    description: &str,
155	) {
156	    present_target_choice(state, source_id, controller, targets, effect, description, true);
157	}
158	
159	// ═══════════════════════════════════════════════════════════════════
160	// Target collection helpers
161	//
162	// Build lists of valid targets for common patterns.
163	// ═══════════════════════════════════════════════════════════════════
164	
165	/// All creatures on the battlefield.
166	pub fn creature_targets(state: &GameState) -> Vec<Target> {
167	    state.objects.values()
168	        .filter(|o| o.zone == Zone::Battlefield && o.power.is_some())
169	        .map(|o| Target::Object(o.id))
170	        .collect()
171	}
172	
173	/// All creatures on the battlefield except a specific one.
174	pub fn creature_targets_except(state: &GameState, exclude: ObjectId) -> Vec<Target> {
175	    state.objects.values()
176	        .filter(|o| o.zone == Zone::Battlefield && o.power.is_some() && o.id != exclude)
177	        .map(|o| Target::Object(o.id))
178	        .collect()
179	}
180	
181	/// All creatures + all players ("any target").
182	pub fn any_targets(state: &GameState) -> Vec<Target> {
183	    let mut targets = creature_targets(state);
184	    for player in &state.players {
185	        targets.push(Target::Player(player.id));
186	    }
187	    targets
188	}
189	
190	/// All creatures + all players, excluding a specific creature.
191	pub fn any_targets_except(state: &GameState, exclude: ObjectId) -> Vec<Target> {
192	    let mut targets = creature_targets_except(state, exclude);
193	    for player in &state.players {
194	        targets.push(Target::Player(player.id));
195	    }
196	    targets
197	}
198	
199	/// All creatures controlled by a specific player.
200	pub fn creatures_controlled_by(state: &GameState, player: PlayerId) -> Vec<Target> {
201	    state.objects.values()
202	        .filter(|o| o.zone == Zone::Battlefield && o.power.is_some() && o.controller == player)
203	        .map(|o| Target::Object(o.id))
204	        .collect()
205	}
206	
207	/// The single opponent in a 2-player game (auto-target convenience).
208	pub fn opponent_player(state: &GameState, controller: PlayerId) -> Target {
209	    Target::Player(state.opponent(controller))
210	}
211	
212	/// Get the controller of a permanent, with a fallback.
213	pub fn controller_of(state: &GameState, object_id: ObjectId) -> PlayerId {
214	    state.get_object(object_id).map(|o| o.controller).unwrap_or(PlayerId(0))
215	}
216	
217	// ═══════════════════════════════════════════════════════════════════
218	// Transform helpers
219	//
220	// Generic transform logic for double-faced cards. Updates all
221	// face-dependent properties (name, keywords, subtypes) so that
222	// obj.keywords always reflects the active face.
223	// ═══════════════════════════════════════════════════════════════════
224	
225	/// Toggle `is_transformed` on a permanent and update all face-dependent
226	/// properties (name, keywords, subtypes) to match the new active face.
227	///
228	/// This is the correct way to transform a DFC. Card-specific code should
229	/// call this instead of manually flipping `obj.is_transformed` and `obj.name`,
230	/// which leaves `obj.keywords` and `obj.subtypes` stale.
231	pub fn apply_transform(state: &mut GameState, object_id: ObjectId, registry: &CardRegistry) {
232	    let (card_id, was_transformed) = match state.get_object(object_id) {
233	        Some(o) if o.zone == Zone::Battlefield => (o.card_id, o.is_transformed),
234	        _ => return,
235	    };
236	
237	    let behavior = match registry.get(card_id) {
238	        Some(b) => b,
239	        None => return,
240	    };
241	
242	    // Flip the transform flag.
243	    if let Some(obj) = state.get_object_mut(object_id) {
244	        obj.is_transformed = !was_transformed;
