                .map(|p| Target::Player(p.id))
                .filter(|t| behavior.is_valid_target(state, caster, t, registry))
                .collect();
            for obj in state.all_objects_in_zone(Zone::Battlefield) {
                let is_pw = obj.card_types.contains(&CardType::Planeswalker)
